const boxes=[...document.querySelectorAll('[data-key]')];const key='xm-career-roadmap-v1';let state={};let available=true;try{state=JSON.parse(localStorage.getItem(key)||'{}')||{};}catch{available=false;}function render(){boxes.forEach(b=>b.checked=state[b.dataset.key]===true);document.querySelector('#progress').textContent=`${boxes.filter(b=>b.checked).length} of ${boxes.length} milestones completed`;}function save(){try{localStorage.setItem(key,JSON.stringify(state));}catch{available=false;document.querySelector('#storage-note').textContent='Browser storage is unavailable. Progress lasts for this visit only.';}}boxes.forEach(b=>b.addEventListener('change',()=>{state[b.dataset.key]=b.checked;save();render();}));document.querySelector('#reset').addEventListener('click',()=>{if(confirm('Reset all roadmap checkboxes?')){state={};save();render();}});render();if(!available)document.querySelector('#storage-note').textContent='Browser storage is unavailable. Progress lasts for this visit only.';
